Client = {
    init: async function (app, container) {
        app = app || session.app;
        container = container || $(".component[name=Client]");
        var clientName = getQueryParameter("Name");
        var clientList = await api.get("DMS/" + app.Config.CRM.ClientFolder + "clientList.json");
        var clientEntry = clientList.filter(r => r.name == clientName)[0];
        $("[name=name]", container).val(clientEntry.name);
        $("[name=contactInfo]",container).val(clientEntry.contactInfo);
        if (!clientEntry.contactInfo) {
            clientEntry.contactInfo = { companyName: null, domain: null, technicalPhone: null, technicalEmail: null, salesPhone: null, salesEmail: null, projectManagerEmail: null, projectManagerEmail: null, history: null };
        }
        var model = kendo.observable(clientEntry.contactInfo);
        kendo.bind($("[name=contactInfo]", container), model);
        loadComponent($("[name=apps]", container), "AppList", async (appListComponent) => {
            await appListComponent.init(app, $(".component[name=AppList]", $("[name=apps]", container)), "DMS/" + app.Config.CRM.ClientFolder + "/" + clientEntry.name + "/apps.json");
        });
        loadComponent($("[name=history]", container), "HistoryList", async (historyListComponent) => {
            await historyListComponent.init(app, $(".component[name=HistoryList]", $("[name=history]", container)), "DMS/" + app.Config.CRM.ClientFolder + "/" + clientEntry.name + "/history.json");
        });
        loadComponent($("[name=themes]", container), "ThemeList", async (themeListComponent) => {
            await themeListComponent.init(app, $(".component[name=ThemeList]", $("[name=themes]", container)), "DMS/" + app.Config.CRM.ClientFolder + "/" + clientEntry.name + "/themes.json", clientEntry);
        });
        $("[name=contactToolbar]").kendoToolBar({
            items: [
                {
                    text: "[resource_displayname[save]]",
                    type: "button",
                    template: "<a name=clientInfoSave style='position: absolute; top: 10px; right:20px; float:right;'><span class='k-icon k-i-save'></span> [resource_displayname[Save]]</a>"
                },
            ]
        });
        $("a[name=clientInfoSave]", container).on("click", async function (e) { await Client.save(app, model, clientName) });
    },

    save: async function (app, clientContactInfo, clientName) {
        var clientList = await api.get("DMS/" + app.Config.CRM.ClientFolder + "clientList.json");
        var clientEntry = clientList.filter(r => r.name == clientName)[0];
        clientEntry.contactInfo = clientContactInfo;
        clientEntry.lastUpdated = (new Date()).toISOString();
        await api.put("DMS/" + app.Config.CRM.ClientFolder + "clientList.json", clientList).then(() =>  notification.success("[resource_displayname[saved]]"))
        .catch((err) => error(err));
    }
}
